"use strict";
// Read values generated by the server; the browser performs no accounting.
document.querySelectorAll('.trend-card').forEach(card => {
  const points = [...card.querySelectorAll('.chart-point')];
  const reading = card.querySelector('.chart-reading');
  const show = point => { reading.textContent = `${point.dataset.chartDate} · ${point.dataset.chartValue}`; };
  points.forEach((point, index) => {
    // One tab stop per chart; arrow keys browse days without 90 tab presses.
    point.tabIndex = index === points.length - 1 ? 0 : -1;
    point.addEventListener('pointerenter', () => show(point));
    point.addEventListener('focus', () => show(point));
    point.addEventListener('keydown', event => {
      let next;
      if (event.key === 'ArrowLeft') next = Math.max(0, index - 1);
      if (event.key === 'ArrowRight') next = Math.min(points.length - 1, index + 1);
      if (event.key === 'Home') next = 0;
      if (event.key === 'End') next = points.length - 1;
      if (next === undefined) return;
      event.preventDefault(); point.tabIndex = -1; points[next].tabIndex = 0; points[next].focus();
    });
  });
});
